const xml = $input.first().json.data || '';
const urls = [...xml.matchAll(/<loc>([^<]+)<\/loc>/g)].map(m => m[1]);
return urls.map(url => ({ json: { url } }));

// Same core checks as tools/seo_audit.py, without third-party code.
const dec = s => s.replace(/&quot;/g, '"').replace(/&#x27;|&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
const out = [];
for (const [n, i] of $input.all().entries()) {
  const url = $('List URLs').all()[n].json.url, html = i.json.body || '', status = i.json.statusCode;
  const title = dec((html.match(/<title>([^<]*)<\/title>/) || [, ''])[1]);
  const desc = dec((html.match(/<meta name="description" content="([^"]*)"/) || [, ''])[1]);
  const canonical = (html.match(/<link rel="canonical" href="([^"]+)"/) || [, ''])[1];
  const h1 = (html.match(/<h1[\s>]/g) || []).length;
  const ld = (html.match(/application\/ld\+json/g) || []).length;
  const issues = [];
  if (status !== 200) issues.push('HTTP ' + status);
  if (title.length < 30 || title.length > 65) issues.push('title length ' + title.length);
  if (desc.length < 70 || desc.length > 165) issues.push('description length ' + desc.length);
  if (canonical !== url) issues.push('canonical ' + (canonical || 'missing'));
  if (h1 !== 1) issues.push(h1 + ' H1');
  if (!ld) issues.push('no JSON-LD');
  if (/name="robots" content="[^"]*noindex/.test(html)) issues.push('noindex on a sitemap URL');
  out.push({ json: { date: new Date().toISOString().slice(0, 10), url, status, title_chars: title.length, description_chars: desc.length, h1, jsonld_blocks: ld, issues: issues.join('; ') || 'none' } });
}
return out;
